import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { topologyFeatures } from './geo.ts';
import { INDICATORS } from './indicators.ts';
import { decodeMatrix } from './matrix.ts';
import {
  indicadoresMetaSchema,
  municipioSchema,
  nomesProcessadosSchema,
  parseMalha,
  ufProcessadaSchema,
} from './schemas.ts';
import { z } from 'zod';

// These tests guard the committed files in src/data/ (generated by `npm run data:fetch`).
const DATA = join(import.meta.dirname, '..', 'data');
const readJson = (name: string): unknown => JSON.parse(readFileSync(join(DATA, name), 'utf8'));

const municipios = z.array(municipioSchema).parse(readJson('municipios.json'));
const ufs = z.array(ufProcessadaSchema).parse(readJson('ufs.json'));
const meta = indicadoresMetaSchema.parse(readJson('indicadores.meta.json'));
const bytes = new Uint8Array(readFileSync(join(DATA, 'indicadores.bin')));
const matrix = decodeMatrix(bytes, meta.linhas, meta.colunas);
const nomes = nomesProcessadosSchema.parse(readJson('nomes.json'));

const column = (id: string) => INDICATORS.findIndex((indicator) => indicator.id === id);

describe('municipios.json and ufs.json', () => {
  it('has every municipality IBGE lists, with unique codes and slugs, sorted by code', () => {
    expect(municipios).toHaveLength(5571);
    expect(new Set(municipios.map((m) => m.codigo)).size).toBe(municipios.length);
    expect(new Set(municipios.map((m) => m.slug)).size).toBe(municipios.length);
    expect(municipios.map((m) => m.codigo)).toEqual(municipios.map((m) => m.codigo).sort());
  });

  it('has 5570 municipalities with data and flags the one without', () => {
    expect(municipios.filter((m) => m.temDados)).toHaveLength(5570);
    expect(municipios.filter((m) => !m.temDados).map((m) => m.slug)).toEqual(['boa-esperanca-do-norte-mt']);
  });

  it('has the 27 states, and every municipality points at one of them', () => {
    expect(ufs).toHaveLength(27);
    const codes = new Set(ufs.map((uf) => uf.codigo));
    expect(municipios.every((m) => codes.has(m.ufCodigo))).toBe(true);
  });
});

describe('indicadores.bin', () => {
  it('matches its meta: one row per municipality, one column per indicator', () => {
    expect(meta.linhas).toBe(municipios.length);
    expect(meta.colunas).toBe(INDICATORS.length);
    expect(meta.indicadores.map((i) => i.id)).toEqual(INDICATORS.map((i) => i.id));
  });

  it('is in sync with the indicator definitions (rerun `npm run data:fetch` after editing them)', () => {
    const hash = createHash('sha256').update(bytes).update(JSON.stringify(INDICATORS)).digest('hex').slice(0, 16);
    expect(meta.hash).toBe(hash);
  });

  it('shows "sem dado" for every cell of a municipality with no data, never 0', () => {
    const row = municipios.findIndex((m) => !m.temDados);
    for (let c = 0; c < matrix.cols; c += 1) expect(matrix.get(row, c)).toBeNull();
  });

  it('never has a zero where a zero is impossible, which would mean a missing value was read as 0', () => {
    for (const id of ['pop', 'area', 'dens', 'idade_mediana', 'envelhecimento', 'pib_pc']) {
      const c = column(id);
      municipios.forEach((m, r) => {
        if (!m.temDados) return;
        const value = matrix.get(r, c);
        if (value !== null) expect(value, `${id} of ${m.slug}`).toBeGreaterThan(0);
      });
    }
  });

  it('keeps share indicators between 0 and 1', () => {
    for (const id of ['urbana_pct', 'esgoto_pct', 'lixo_pct']) {
      const c = column(id);
      municipios.forEach((m, r) => {
        const value = matrix.get(r, c);
        if (value !== null) {
          expect(value, `${id} of ${m.slug}`).toBeGreaterThanOrEqual(0);
          expect(value, `${id} of ${m.slug}`).toBeLessThanOrEqual(1);
        }
      });
    }
  });

  it('reports coverage that matches the matrix', () => {
    meta.indicadores.forEach((indicator, c) => {
      let present = 0;
      for (let r = 0; r < matrix.rows; r += 1) if (matrix.get(r, c) !== null) present += 1;
      expect(indicator.cobertura, indicator.id).toBe(present);
    });
  });
});

describe('nomes.json', () => {
  it('has an entry for every municipality, at most 20 names each, most frequent first', () => {
    expect(Object.keys(nomes.porMunicipio).sort()).toEqual(municipios.map((m) => m.codigo));
    for (const lista of Object.values(nomes.porMunicipio)) {
      expect(lista.length).toBeLessThanOrEqual(20);
      const frequencias = lista.map((n) => n.frequencia);
      expect(frequencias).toEqual([...frequencias].sort((a, b) => b - a));
    }
  });

  it('is labelled with the 2010 Census, since newer municipalities have no names', () => {
    expect(nomes.ano).toBe(2010);
  });
});

describe('malhas', () => {
  const MAX_BYTES = 1_000_000;
  const meshText = (relative: string) => readFileSync(join(DATA, 'malhas', relative), 'utf8');
  const codes = (relative: string) => topologyFeatures(parseMalha(JSON.parse(meshText(relative)))).map((item) => item.codigo);

  it('keeps every mesh file under 1 MB', () => {
    expect(Buffer.byteLength(meshText('uf.topo.json'))).toBeLessThan(MAX_BYTES);
    for (const uf of ufs) {
      const size = Buffer.byteLength(meshText(`uf/${uf.sigla.toLowerCase()}.topo.json`));
      expect(size, uf.sigla).toBeLessThan(MAX_BYTES);
    }
  });

  it('has the 27 states in the country mesh', () => {
    expect(codes('uf.topo.json').sort()).toEqual(ufs.map((uf) => uf.codigo));
  });

  it("has each state's municipalities in its own mesh, and only those", () => {
    for (const uf of ufs) {
      const expected = municipios.filter((m) => m.ufCodigo === uf.codigo && m.lat !== null).map((m) => m.codigo);
      expect(codes(`uf/${uf.sigla.toLowerCase()}.topo.json`).sort(), uf.sigla).toEqual(expected);
    }
  });

  it('gives a centroid inside Brazil to every municipality that has geometry', () => {
    const withGeometry = municipios.filter((m) => m.lat !== null);
    expect(withGeometry).toHaveLength(5570);
    expect(municipios.filter((m) => m.lat === null).map((m) => m.slug)).toEqual(['boa-esperanca-do-norte-mt']);
  });
});

describe('ufs.json state figures', () => {
  it('sums to the 2022 Census population of Brazil', () => {
    expect(ufs.reduce((total, uf) => total + uf.populacao, 0)).toBe(203080756);
  });
});
